      return jsonResponse(TARGET_ENDPOINTS[0].response, 200)
    })
    const payload: AirtableWebhookPayload = { id: 'rec1', Name: 'Test', 'Created time': '2024-01-15T10:30:00.000Z' }
    const config: ConnectorConfig = { webhookUrl: 'https://discord.com/api/webhooks/123/abc', fetch }
