export interface ConnectorConfig {
  airtableApiKey: string
  airtableBaseId: string
  airtableTableName: string
  fetch?: typeof fetch
}

export interface ShopifyOrderPaidPayload {
  id: number
  email: string
  total_price: string
}

export interface AirtableCreateRecordResponse {
  id: string
  fields: {
    'Order ID': number
    Email: string
    Total: string
  }
  createdTime: string
}

export interface HandleResult {
  airtableRecordId: string
  createdTime: string
}

function validatePayload(payload: unknown): asserts payload is ShopifyOrderPaidPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (typeof p.id !== 'number') {
    throw new Error('Missing required field: id (number)')
  }
  if (typeof p.email !== 'string') {
    throw new Error('Missing required field: email (string)')
  }
  if (typeof p.total_price !== 'string') {
    throw new Error('Missing required field: total_price (string)')
  }
}

export async function handle(
  payload: ShopifyOrderPaidPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)

  const fetchFn = config.fetch ?? fetch
  const url = `https://api.airtable.com/v0/${config.airtableBaseId}/${config.airtableTableName}`

  const body = {
    fields: {
      'Order ID': payload.id,
      Email: payload.email,
      Total: payload.total_price,
    },
  }

  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      'X-Auth-Token': `${config.airtableApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`Airtable API error: ${response.status} ${response.statusText} at POST ${url}`)
  }

  const data = (await response.json()) as AirtableCreateRecordResponse

  return {
    airtableRecordId: data.id,
    createdTime: data.createdTime,
  }
}

